import{z as A,x as s,o as n,c as d,q as B,j as l,D as E,d as r,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"逆向选择的动态版本","description":"","frontmatter":{"title":"逆向选择的动态版本","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/obd-adverse-dynamic.md","filePath":"quant/obd-adverse-dynamic.md","lastUpdated":1791413859000}'),m={name:"quant/obd-adverse-dynamic.md"};function p(c,a,h,u,D,F){const t=s("Mermaid");return n(),d("div",null,[a[2]||(a[2]=B('<h1 id="逆向选择的动态版本" tabindex="-1">逆向选择的动态版本 <a class="header-anchor" href="#逆向选择的动态版本" aria-label="Permalink to &quot;逆向选择的动态版本&quot;">​</a></h1><div class="epigraph"><p>静态模型告诉你平均要为逆向选择留多宽的价差；动态版本回答的是此刻——安静时段留宽了是白付，毒性时段留窄了是送钱。</p><footer>—— 据 Glosten and Milgrom, Journal of Financial Economics, 1985；Kyle, Econometrica, 1985；Harris, Trading and Exchanges, 2003 整理</footer></div><p><a href="/quant/obd-flow-statespace">上一课</a>把多通道流量收成状态估计与不确定性。本课回到流动性提供者最核心的损失：逆向选择。静态版本主干已经讲过：<a href="/quant/glosten-milgrom">Glosten-Milgrom</a> 的单期价差补偿与 <a href="/quant/kyle-model">Kyle 模型</a>的线性 \\(\\lambda\\)。本课写动态版本：知情比例是随时间与体制变化的状态，价差与报价偏移是它的条件函数，而「现在多毒」这个状态的输入，正是上一课的滤波输出。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态价差是全程平均账：按平均知情比例设的半价差，安静时段给得太宽——白付成交机会，毒性时段给得太窄——点差内亏损。回归口径的 \\(\\lambda\\) 同病：按窗口平均的深度倒数掩盖了流的状态切换，流持续同号的时段，真实响应远高于窗口均值。做市系统若以常数参数运行，毒潮的亏损正好吃掉安静时段的全部利润——这是逆向选择必须动态化的全部理由。</p><p><span class="marginnote">术语翻译：逆向选择就是「和你成交的人，往往在挑你便宜的那一刻恰好更懂行情」。价差的本质不是手续费，而是做市商为「被更懂的人挑中」支付的保险费；动态版本要回答的是保险费此刻该定多少。</span></p><h3 id="毒性作为状态函数" tabindex="-1">毒性作为状态函数 <a class="header-anchor" href="#毒性作为状态函数" aria-label="Permalink to &quot;毒性作为状态函数&quot;">​</a></h3><p>事后毒性有现成度量：有效价差减实现价差，差值是成交后被逆向选择吃掉的份额，窗口口径见<a href="/quant/effective-realized-spread">有效与实现价差</a>；流的口径用<a href="/quant/ofi-toxicity">持续同号的 OFI</a>。动态化就是把这个事后量做成状态的函数：用滤波状态与创新对事后损失回归，按体制分箱得条件毒性曲线；报价端把半价差与偏移写成它的增函数。在 Avellaneda–Stoikov 框架里，这一步等价于把常数强度换成状态依赖的毒性项。</p><p><span class="marginnote">实现价差的窗口选择就是「逆向选择的半衰期」：同一批成交，按成交后一分钟与五分钟算出的实现价差可以一正一负。报告动态毒性必须带窗口口径，否则安静与毒潮的比较没有意义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在线回路四步。滤波：流量观测进状态估计，输出净方向、毒性强度与不确定性。条件定价：半价差 \\(=\\) 事后损失的条件期望 \\(+\\) 风险与库存项；不确定性大时少动价。事后回收：已成交订单的后续中间价路径落地成实现价差，按窗口分档记账。状态回归更新：新样本回到条件毒性曲线，体制切换由创新触发，不等日级复盘。闭环在此成形：价差决定你吸引什么样的流，流反过来更新毒性估计——报价在筛选自己的对手方。</p>',11)),(n(),l(o,null,{default:E(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILT%5B%22%E6%B5%81%E9%87%8F%E6%BB%A4%E6%B3%A2%E7%8A%B6%E6%80%81%22%5D%20--%3E%20TOX%5B%22%E6%9D%A1%E4%BB%B6%E6%AF%92%E6%80%A7%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20TOX%20--%3E%20QUOTE%5B%22%E5%8D%8A%E4%BB%B7%E5%B7%AE%20%2B%20%E5%81%8F%E7%A7%BB%22%5D%0A%20%20QUOTE%20--%3E%20FILL%5B%22%E6%88%90%E4%BA%A4%E4%B8%8E%E5%AF%B9%E6%89%8B%E6%96%B9%E6%9E%84%E6%88%90%22%5D%0A%20%20FILL%20--%3E%20RS%5B%22%E5%AE%9E%E7%8E%B0%E4%BB%B7%E5%B7%AE%EF%BC%88%E5%88%86%E7%AA%97%E5%8F%A3%EF%BC%89%22%5D%0A%20%20RS%20--%3E%20REG%5B%22%E7%8A%B6%E6%80%81%E5%9B%9E%E5%BD%92%E6%9B%B4%E6%96%B0%22%5D%0A%20%20REG%20--%3E%20TOX%0A%20%20INNO%5B%22%E5%88%9B%E6%96%B0%EF%BC%9A%E6%B5%81%E9%87%8F%E6%84%8F%E5%A4%96%22%5D%20--%3E%20TOX%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"贝叶斯结构是核心：一笔成交不只是头寸变化，还是关于对手方类型的信号——被成交这件事本身更新后验，报价是对更新后损失的公平补偿加风险溢价。静态模型把这个后验平均掉，动态版本保留它的时变。第二层是筛选：价差变宽改变来流构成，犹豫的单子绕行、知情的照样来，条件毒性的估计要意识到「样本是价差自己的函数」，否则回归把筛选效应记成毒性上升。第三层是时段耦合：收盘前与公告窗前的知情比例有日历结构，通向后面的日内形状课。",-1)),a[5]||(a[5]=e("p",null,"单笔成交在贝叶斯回路里走多远，取决于它与当前方向预期的关系——这正是「被成交即被更新」的细节图景：",-1)),(n(),l(o,null,{default:E(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILL%5B%22%E4%B8%80%E7%AC%94%E5%B8%82%E4%BB%B7%E5%8D%95%E5%90%83%E6%8E%89%E6%88%91%E7%9A%84%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20CMP%7B%22%E6%96%B9%E5%90%91%E4%B8%8E%E8%BF%91%E6%AE%B5%E5%87%80%E6%B5%81%E5%90%8C%E5%8F%B7%3F%22%7D%0A%20%20CMP%20--%3E%7C%22%E5%90%8C%E5%8F%B7%3A%E5%83%8F%E7%9F%A5%E6%83%85%E5%8D%95%22%7C%20UP%5B%22%E6%AF%92%E6%80%A7%E5%90%8E%E9%AA%8C%E4%B8%8A%E8%B0%83%22%5D%0A%20%20CMP%20--%3E%7C%22%E4%B8%8D%E5%90%8C%E5%8F%B7%3A%E5%83%8F%E5%99%AA%E5%A3%B0%E5%8D%95%22%7C%20FLAT%5B%22%E6%AF%92%E6%80%A7%E5%90%8E%E9%AA%8C%E5%9F%BA%E6%9C%AC%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20UP%20--%3E%20WID%5B%22%E4%B8%8B%E4%B8%80%E6%A1%A3%E5%8D%8A%E4%BB%B7%E5%B7%AE%E5%8A%A0%E5%AE%BD%22%5D%0A%20%20FLAT%20--%3E%20HOLD%5B%22%E5%8D%8A%E4%BB%B7%E5%B7%AE%E7%BB%B4%E6%8C%81%22%5D%0A%20%20WID%20--%3E%20MIX%5B%22%E6%9D%A5%E6%B5%81%E6%9E%84%E6%88%90%E6%94%B9%E5%8F%98%3A%E7%8A%B9%E8%B1%AB%E5%8D%95%E7%BB%95%E8%A1%8C%22%5D%0A%20%20HOLD%20--%3E%20MIX%0A%20%20MIX%20--%3E%20FILL%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">数字实例：设平均知情比例 20%，按平均账定半价差 2 分钱。毒潮时段真实比例冲到 60%，同一笔顺势成交的事后损失约为安静时段（5%）的十二倍——常数参数在两头同时吃亏：安静时白付价差吓跑正常流，毒潮时价差远不够赔。</span></p><p>常见错误：把事前补偿与事后毒性混为一谈——用后者直接反推前者会吃进筛选偏差；毒性检测跑在日级频率上，毒潮半天走完，检测到时利润已吐完；把库存与毒性管理混在一个偏移项里，归因从此失真。</p><p><span class="marginnote">常见误区：初学者容易以为价差变宽是「做市商怕了」，收缩价差才是竞争力。实际上毒潮中坚持窄价差等于免费承保：实现价差会把你上一小时赚的点差全部退回去，价差宽窄本来就是状态变量而不是态度问题。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>条件毒性曲线依赖状态估计的质量，上一课的盲区（冰山、合并口径）原样传进来。事后度量有窗口任意性，窗口内还叠着市场-wide 变动，个股毒性要与共同流动性冲击分开——那是共同因子课的对象。极端情形下动态定价会自我实现：毒潮中价差拉宽到无人成交，估计器断粮，状态停在过时值。识别的边界照旧：约化模型只承诺「照这个状态报价的历史损失更小」，不承诺对手方真是知情人。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>动态逆向选择 = 把知情比例做成状态函数：价差是条件期望的补偿，不是全程平均。</li><li>事后度量两件套：有效与实现价差之差、持续同号 OFI；报告必须带窗口口径。</li><li>在线回路四步：滤波、条件定价、事后回收、状态回归；切换由创新触发。</li><li>报价筛选来流：毒性回归要意识到样本是价差自己的函数。</li><li>出处：Glosten and Milgrom, <em>JFE</em>, 1985；Kyle, <em>Econometrica</em>, 1985；工程框架见 Cartea, Jaimungal and Penalva, <em>Algorithmic and High-Frequency Trading</em>, 2015；市场语言见 Harris, <em>Trading and Exchanges</em>, 2003。</li></ul>',7))])}const C=A(m,[["render",p]]);export{T as __pageData,C as default};
